// 以 Asia/Taipei 計算「上一個完整週」：上週一 00:00 ~ 上週日 23:59:59
const OFFSET_MS = 8 * 60 * 60 * 1000;
const nowTpe = new Date(Date.now() + OFFSET_MS);

// 用 getUTC* 讀取，等同讀取台北牆上時間
const dow = nowTpe.getUTCDay();          // 0=週日
const daysSinceMonday = (dow + 6) % 7;   // 週一=0

const thisMonday = Date.UTC(
  nowTpe.getUTCFullYear(), nowTpe.getUTCMonth(), nowTpe.getUTCDate() - daysSinceMonday
);
const startMs = thisMonday - 7 * 86400000;
const endMs = thisMonday - 1000;

const pad = (n) => String(n).padStart(2, '0');
const fmtDate = (ms) => {
  const d = new Date(ms);
  return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate());
};
const fmtIso = (ms) => {
  const d = new Date(ms);
  return fmtDate(ms) + 'T' + pad(d.getUTCHours()) + ':' + pad(d.getUTCMinutes()) + ':' + pad(d.getUTCSeconds()) + '+08:00';
};

// ISO 8601 週次
function isoWeek(ms) {
  const d = new Date(ms);
  const t = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
  const day = (t.getUTCDay() + 6) % 7;
  t.setUTCDate(t.getUTCDate() - day + 3);            // 移到該週週四
  const firstThu = new Date(Date.UTC(t.getUTCFullYear(), 0, 4));
  const fday = (firstThu.getUTCDay() + 6) % 7;
  firstThu.setUTCDate(firstThu.getUTCDate() - fday + 3);
  const week = 1 + Math.round((t.getTime() - firstThu.getTime()) / (7 * 86400000));
  return { year: t.getUTCFullYear(), week };
}

const w = isoWeek(startMs);

return [{
  json: {
    區間開始: fmtIso(startMs),
    區間結束: fmtIso(endMs),
    區間開始日: fmtDate(startMs),
    區間結束日: fmtDate(endMs),
    ISO週次: w.year + '-W' + pad(w.week),
    年度: w.year,
    上架日期: fmtDate(Date.now() + OFFSET_MS),
    起始毫秒: startMs - OFFSET_MS,
    結束毫秒: endMs - OFFSET_MS,
  }
}];

// 把 專案 × 群組 × LINE項目 組裝成「每個專案一筆」的 LLM 輸入
const 週期 = $('計算週期').first().json;

const SYSTEM_PROMPT = "你是台灣室內設計公司「川果設計 NID DESIGN LAB」的專案助理，負責整理每週專案週報。\n\n嚴格遵守以下規則：\n1. 只根據提供的資料撰寫。資料裡沒有的事情絕對不可以寫。寧可少寫也不要編造。\n2.「結論」只放本週已拍板、不會再變的決定。還在討論中的事、單純的進度描述都不算。\n3.「代辦」只放有明確負責人且尚未完成的行動。沒有負責人的模糊期待不要放。\n4.「追蹤」放跨週未結案、需要持續盯的事項。本週產生且本週已完成的事不要放。\n5. 每個群組的摘要控制在 2-4 條，用台灣室內設計業界慣用語。\n6. 涉及業主的群組用詞要中性客觀，不要出現對業主的評價。\n7. 若某群組本週沒有資料，該群組的「重點」回傳空陣列，不要硬掰。\n\n輸出必須是 JSON，格式如下：\n{\n  \"群組摘要\": [{\"群組名稱\":\"...\",\"重點\":[\"...\",\"...\"]}],\n  \"結論\": [\"...\"],\n  \"代辦\": [{\"事項\":\"...\",\"負責人\":\"...\",\"期限\":\"YYYY-MM-DD 或空字串\"}],\n  \"追蹤\": [{\"事項\":\"...\",\"說明\":\"...\"}],\n  \"決策摘要\": \"一句話講本週最重要的決定\",\n  \"風險等級\": \"正常 或 注意 或 警示\",\n  \"議題標籤\": [\"從 設計變更/追加預算/工期延誤/材料選樣/驗收缺失/請款/法規/客訴/人力調度/安全衛生 中挑適用的\"],\n  \"涉及金額變動\": true 或 false\n}";

const txt = (p) => {
  if (!p) return '';
  if (p.type === 'title') return (p.title || []).map(t => t.plain_text).join('');
  if (p.type === 'rich_text') return (p.rich_text || []).map(t => t.plain_text).join('');
  if (p.type === 'select') return p.select ? p.select.name : '';
  if (p.type === 'number') return p.number;
  if (p.type === 'checkbox') return p.checkbox;
  return '';
};

// --- 專案 ---
const 專案清單 = (($('查專案').first().json.results) || []).map(p => ({
  pageId: p.id,
  名稱: txt(p.properties['專案名稱']),
  代號: txt(p.properties['專案代號']) || 'NOCODE',
  slackChannelId: txt(p.properties['Slack Channel ID']),
}));

// --- 群組登錄 ---
const 群組清單 = (($('查群組登錄').first().json.results) || []).map(g => ({
  pageId: g.id,
  名稱: txt(g.properties['群組名稱']),
  平台: txt(g.properties['平台']),
  groupId: txt(g.properties['群組 ID']),
  類型: txt(g.properties['群組類型']) || '其他',
  權重: txt(g.properties['排序權重']),
  重點指示: txt(g.properties['摘要重點指示']),
  敏感度: txt(g.properties['敏感度']),
  專案PageIds: ((g.properties['所屬專案'] || {}).relation || []).map(r => r.id),
}));

// --- LINE 工作項目：容錯處理不同回傳結構 ---
const raw = $('抓 LINE 工作項目').first().json;
const 全部項目 = Array.isArray(raw) ? raw
  : Array.isArray(raw.items) ? raw.items
  : Array.isArray(raw.results) ? raw.results
  : Array.isArray(raw.data) ? raw.data
  : [];

const 取時間 = (it) => {
  const v = it.created_at || it.sent_at || it.createdAt || it.due_at || null;
  if (!v) return null;
  const ms = typeof v === 'number' ? (v < 1e12 ? v * 1000 : v) : Date.parse(v);
  return Number.isNaN(ms) ? null : ms;
};

const 區間內項目 = 全部項目.filter(it => {
  const ms = 取時間(it);
  return ms !== null && ms >= 週期.起始毫秒 && ms <= 週期.結束毫秒;
});

const out = [];
for (const 專案 of 專案清單) {
  const 本案群組 = 群組清單
    .filter(g => g.專案PageIds.includes(專案.pageId))
    .sort((a, b) => (a.權重 == null ? 90 : a.權重) - (b.權重 == null ? 90 : b.權重));

  const 分段 = 本案群組.map(g => {
    const 該群項目 = 區間內項目.filter(it => (it.group_id || it.groupId) === g.groupId);
    return {
      群組名稱: g.名稱,
      群組類型: g.類型,
      重點指示: g.重點指示,
      敏感度: g.敏感度,
      則數: 該群項目.length,
      內容: 該群項目.map(it => ({
        分類: it.category || it.type || 'info',
        標題: it.title || '',
        說明: it.details || it.text || '',
        負責人: it.owner || '',
        期限: it.due_at || '',
      })),
    };
  });

  const 總則數 = 分段.reduce((s, d) => s + d.則數, 0);

  out.push({
    json: Object.assign({}, 週期, {
      專案PageId: 專案.pageId,
      專案名稱: 專案.名稱,
      專案代號: 專案.代號,
      slackChannelId: 專案.slackChannelId,
      群組PageIds: 本案群組.map(g => g.pageId),
      總則數: 總則數,
      資料完整度: 本案群組.length === 0 ? '來源異常' : (總則數 === 0 ? '部分缺漏' : '完整'),
      systemPrompt: SYSTEM_PROMPT,
      userPrompt: [
        '專案：' + 專案.名稱 + '（' + 專案.代號 + '）',
        '摘要區間：' + 週期.區間開始日 + ' 至 ' + 週期.區間結束日,
        '',
        '以下是各群組本週的討論資料（已依週報顯示順序排列）：',
        '',
        JSON.stringify(分段, null, 2),
      ].join('\n'),
    })
  });
}

if (out.length === 0) {
  throw new Error('沒有任何符合條件的專案。請確認「01｜專案」至少有一筆勾選了「納入週報」。');
}
return out;

// 解析 LLM 回傳，組出 Notion 與 Slack 需要的內容
const 來源全部 = $('組裝專案資料').all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const 來源 = 來源全部[i].json;
  let 摘要;
  try {
    摘要 = JSON.parse(items[i].json.choices[0].message.content);
  } catch (e) {
    摘要 = {
      群組摘要: [], 結論: [], 代辦: [], 追蹤: [],
      決策摘要: '（摘要解析失敗，請檢查 OpenAI 回傳）',
      風險等級: '注意', 議題標籤: [], 涉及金額變動: false,
    };
  }

  const 標題 = '[' + 來源.專案代號 + '] ' + 來源.ISO週次 + ' 週報';
  const 燈號 = 摘要.風險等級 === '警示' ? '🔴' : (摘要.風險等級 === '注意' ? '🟡' : '🟢');

  // --- Slack 版型 ---
  const L = [];
  L.push('📋 *' + 來源.專案名稱 + ' 週報｜' + 來源.ISO週次 + '*');
  L.push('摘要區間：' + 來源.區間開始日 + ' – ' + 來源.區間結束日 + '　' + 燈號 + ' ' + (摘要.風險等級 || '正常'));
  L.push('─────────────────────────────');
  L.push('');

  for (const g of (摘要.群組摘要 || [])) {
    if (!g.重點 || g.重點.length === 0) continue;
    L.push('*' + g.群組名稱 + '*');
    for (const p of g.重點) L.push('　　• ' + p);
    L.push('');
  }

  L.push('─────────────────────────────');
  L.push('📌 *整體摘要*');
  L.push('');
  L.push('*【結論】*');
  if ((摘要.結論 || []).length) {
    摘要.結論.forEach((c, n) => L.push('　' + (n + 1) + '. ' + c));
  } else { L.push('　（本週無已拍板事項）'); }
  L.push('');
  L.push('*【代辦】*');
  if ((摘要.代辦 || []).length) {
    摘要.代辦.forEach((t, n) => {
      const who = t.負責人 ? '　@' + t.負責人 : '';
      const due = t.期限 ? '　期限 ' + t.期限 : '';
      L.push('　' + (n + 1) + '. ' + t.事項 + who + due);
    });
  } else { L.push('　（本週無新增代辦）'); }
  L.push('');
  L.push('*【追蹤】*');
  if ((摘要.追蹤 || []).length) {
    摘要.追蹤.forEach(t => L.push('　⚠️ ' + t.事項 + ' — ' + t.說明));
  } else { L.push('　（無跨週未結案事項）'); }
  L.push('');
  L.push('📊 本週訊息 ' + 來源.總則數 + ' 則　|　資料完整度：' + 來源.資料完整度);

  // --- Notion 頁面內文 ---
  const N = [];
  for (const g of (摘要.群組摘要 || [])) {
    if (!g.重點 || g.重點.length === 0) continue;
    N.push('## ' + g.群組名稱);
    for (const p of g.重點) N.push('- ' + p);
    N.push('');
  }
  N.push('## 結論');
  (摘要.結論 || []).forEach(c => N.push('- ' + c));
  N.push('');
  N.push('## 代辦');
  (摘要.代辦 || []).forEach(t => {
    const who = t.負責人 ? '（' + t.負責人 + '）' : '';
    const due = t.期限 ? ' 期限 ' + t.期限 : '';
    N.push('- ' + t.事項 + who + due);
  });
  N.push('');
  N.push('## 追蹤');
  (摘要.追蹤 || []).forEach(t => N.push('- ' + t.事項 + ' — ' + t.說明));

  out.push({
    json: Object.assign({}, 來源, {
      標題: 標題,
      摘要: 摘要,
      slackText: L.join('\n'),
      notionBody: N.join('\n'),
    })
  });
}

return out;

parameters.jsonBody:
={{ JSON.stringify({
  parent: { database_id: '47d6b48d-8f7c-4685-bde5-c1b1519a1313' },
  properties: {
    '標題': { title: [{ text: { content: $json.標題 } }] },
    'ISO 週次': { rich_text: [{ text: { content: $json.ISO週次 } }] },
    '年度': { number: $json.年度 },
    '上架日期': { date: { start: $json.上架日期 } },
    '摘要區間': { date: { start: $json.區間開始日, end: $json.區間結束日 } },
    '專案': { relation: [{ id: $json.專案PageId }] },
    '來源群組': { relation: $json.群組PageIds.map(id => ({ id })) },
    '狀態': { select: { name: '草稿' } },
    '產生方式': { select: { name: '自動' } },
    '風險等級': { select: { name: $json.摘要.風險等級 || '正常' } },
    '資料完整度': { select: { name: $json.資料完整度 } },
    '決策摘要': { rich_text: [{ text: { content: String($json.摘要.決策摘要 || '').slice(0, 1900) } }] },
    '議題標籤': { multi_select: ($json.摘要.議題標籤 || []).map(n => ({ name: n })) },
    '涉及金額變動': { checkbox: !!$json.摘要.涉及金額變動 },
    '有未決事項': { checkbox: ($json.摘要.追蹤 || []).length > 0 },
    '訊息則數': { number: $json.總則數 },
    '新增待辦數': { number: ($json.摘要.代辦 || []).length }
  },
  children: [{
    object: 'block', type: 'paragraph',
    paragraph: { rich_text: [{ text: { content: $json.notionBody.slice(0, 1900) } }] }
  }]
}) }}
